### Mã nguồn Node.js ký số và tạo báo giá chuyến giao hàng xe tải Lalamove:

```javascript
import crypto from 'crypto';
import axios from 'axios';
import dotenv from 'dotenv';
dotenv.config();

function taoChuKyLalamove(time, method, path, body, secret) {
  const raw = `${time}
${method}
${path}

${body}`;
  return crypto.createHmac('sha256', secret).update(raw).digest('hex');
}

async function layBaoGiaLalamove(bodyData) {
  const time = Date.now().toString();
  const method = 'POST';
  const path = '/v3/quotations';
  const bodyStr = JSON.stringify(bodyData);
  const signature = taoChuKyLalamove(time, method, path, bodyStr, process.env.LALAMOVE_API_SECRET);

  try {
    const res = await axios.post(`https://rest.sandbox.lalamove.com${path}`, bodyData, {
      headers: {
        'Authorization': `hmac ${process.env.LALAMOVE_API_KEY}:${time}:${signature}`,
        'Market': 'VN',
        'Content-Type': 'application/json'
      }
    });
    console.log('Báo giá xe tải Lalamove:', res.data.data.totalFee, res.data.data.totalFeeCurrency);
    return res.data.data;
  } catch (err) {
    console.error('Lỗi Lalamove:', err.response ? err.response.data : err.message);
  }
}

layBaoGiaLalamove({
  serviceType: 'TRUCK500', // Xe tải 500kg
  stops: [
    { coordinates: { lat: '10.7725', lng: '106.6980' }, address: 'Kho hàng Quận 1' },
    { coordinates: { lat: '10.8231', lng: '106.6297' }, address: 'Đại lý Quận 12' }
  ]
});
```

