```javascript
import axios from 'axios';
import dotenv from 'dotenv';
dotenv.config();

async function guiCuocGoiVoiceOtp(soDienThoai, maOtp) {
  const url = 'https://api.speedsms.vn/index.php/voice/otp';
  const token = process.env.SPEEDSMS_ACCESS_TOKEN;

  const authHeader = 'Basic ' + Buffer.from(token + ':x').toString('base64');

  const duLieu = {
    to: soDienThoai,
    otp: maOtp
  };

  try {
    const response = await axios.post(url, duLieu, {
      headers: {
        'Authorization': authHeader,
        'Content-Type': 'application/json'
      }
    });

    if (response.data.status === 'success') {
      console.log('Đã khởi tạo cuộc gọi Voice OTP thành công:', response.data.data);
      return response.data.data;
    } else {
      console.error('Lỗi từ SpeedSMS:', response.data.message);
    }
  } catch (error) {
    console.error('Lỗi khi gọi API SpeedSMS:', error.message);
  }
}

// Thực hiện cuộc gọi đọc mã OTP tới khách hàng
guiCuocGoiVoiceOtp('0987654321', '654321');
```

