### Mã nguồn Node.js khởi tạo giao dịch thanh toán mã QR SmartPay:

```javascript
import crypto from 'crypto';
import axios from 'axios';
import dotenv from 'dotenv';
dotenv.config();

function sinhChuKySmartPay(duLieuYeuCau, secureSecret) {
  const sortedData = Object.keys(duLieuYeuCau).sort().map(k => `${k}=${duLieuYeuCau[k]}`).join('&');
  return crypto.createHmac('sha256', secureSecret).update(sortedData).digest('hex');
}

async function taoMaThanhToanSmartPay(maDonHang, soTien, noiDung) {
  const url = `${process.env.SMARTPAY_GATEWAY_URL}/create-qr`;

  const duLieu = {
    merchant_id: process.env.SMARTPAY_MERCHANT_ID,
    order_id: maDonHang,
    amount: soTien,
    currency: 'VND',
    description: noiDung,
    return_url: 'https://cuahang.vn/thanh-toan-hoan-tat',
    timestamp: Math.floor(Date.now() / 1000)
  };

  duLieu.signature = sinhChuKySmartPay(duLieu, process.env.SMARTPAY_SECURE_SECRET);

  try {
    const response = await axios.post(url, duLieu, {
      headers: { 'Content-Type': 'application/json' }
    });

    if (response.data.code === '00') {
      console.log('Tạo mã QR SmartPay thành công:', response.data.qr_code_string);
      return response.data;
    } else {
      console.error('Lỗi tạo mã QR SmartPay:', response.data.message);
    }
  } catch (error) {
    console.error('Lỗi kết nối cổng thanh toán SmartPay:', error.message);
  }
}

// Khởi tạo mã thanh toán hóa đơn
taoMaThanhToanSmartPay('DH-2026-9901', 250000, 'Thanh toan don hang tra sua');
```

