usageGuideVi:
### Mã nguồn Node.js ký số và truy vấn sản phẩm từ Lazada Việt Nam:

```javascript
import crypto from 'crypto';
import axios from 'axios';
import dotenv from 'dotenv';
dotenv.config();

function taoChuKyLazada(duongDanApi, thamSo, appSecret) {
  const sortedKeys = Object.keys(thamSo).sort();
  let chuoiGoc = duongDanApi;
  for (const k of sortedKeys) {
    chuoiGoc += k + thamSo[k];
  }
  return crypto.createHmac('sha256', appSecret).update(chuoiGoc).digest('hex').toUpperCase();
}

async function layDanhSachSanPhamLazada() {
  const endpoint = 'https://api.lazada.vn/rest';
  const apiPath = '/products/get';
  const timestamp = Date.now().toString();

  const thamSo = {
    app_key: process.env.LAZADA_APP_KEY,
    timestamp: timestamp,
    sign_method: 'sha256',
    access_token: process.env.LAZADA_ACCESS_TOKEN,
    filter: 'all',
    limit: '20'
  };

  thamSo.sign = taoChuKyLazada(apiPath, thamSo, process.env.LAZADA_APP_SECRET);

  try {
    const response = await axios.get(`${endpoint}${apiPath}`, { params: thamSo });
    console.log('Tổng số sản phẩm trên gian hàng:', response.data.data.total_products);
    return response.data.data;
  } catch (error) {
    console.error('Lỗi gọi API Lazada:', error.message);
  }
}

layDanhSachSanPhamLazada();
```

