usageGuideVi:
### Mã nguồn Node.js ký số và truy vấn danh sách đơn hàng TikTok Shop:

```javascript
import crypto from 'crypto';
import axios from 'axios';
import dotenv from 'dotenv';
dotenv.config();

function taoChuKyTikTokShop(duongDan, thamSo, appSecret) {
  // Sắp xếp các tham số theo thứ tự bảng chữ cái
  const keys = Object.keys(thamSo).filter(k => k !== 'sign' && k !== 'access_token').sort();
  let chuoiKy = duongDan;
  for (const k of keys) {
    chuoiKy += k + thamSo[k];
  }

  return crypto.createHmac('sha256', appSecret).update(chuoiKy).digest('hex');
}

async function layDanhSachDonHangMoi() {
  const host = 'https://open-api.tiktokglobalshop.com';
  const path = '/order/202309/orders/search';

  const thamSo = {
    app_key: process.env.TIKTOK_APP_KEY,
    timestamp: Math.floor(Date.now() / 1000),
    page_size: '20'
  };

  const sign = taoChuKyTikTokShop(path, thamSo, process.env.TIKTOK_APP_SECRET);
  thamSo.sign = sign;
  thamSo.access_token = process.env.TIKTOK_ACCESS_TOKEN;

  try {
    const response = await axios.post(`${host}${path}`, {
      order_status: 'AWAITING_SHIPMENT' // Đơn hàng đang chờ đóng gói giao vận
    }, {
      params: thamSo,
      headers: { 'Content-Type': 'application/json' }
    });

    console.log('Số lượng đơn hàng cần xử lý:', response.data.data.orders.length);
    return response.data.data.orders;
  } catch (error) {
    console.error('Lỗi khi truy vấn TikTok Shop:', error.response ? error.response.data : error.message);
  }
}

layDanhSachDonHangMoi();
```

